head.script:

 	/****************************************************
 	 * 화면명 : number_multiFormat.xml
 	 * 화면 설명 : 숫자_멀티포맷
 	 * 작 성 자  : 김형준
 	 * 최초 작성 : 2022-04-25
 	 ****************************************************/

 	/*******************************
 	* 그리드 날짜 데이터
 	********************************/ 
    scwin.jsonData1 = [
        {
            "type01" : "12345678",
            "type02" : "12345678.12345",
        },
        {
            "type01" : "12345678",
            "type02" : "12345678.12",
        },
        {
            "type01" : "12345678",
            "type02" : "12345678.123",
        },
        {
            "type01" : "12345678",
            "type02" : "12345678.1234",
        },
    ];

    /*******************************
    * 화면 초기 로딩 시 호출
    ********************************/
    scwin.onpageload = function() {
        gcm = {};
        gcm.NUMBER_FORMAT = 2; //1이면 #,###.## 포맷 | 2이면 #.###,## 포맷

        scwin.searchEuroAutoFormat();
        scwin.gridEuroAutoFormat();
    };

    scwin.searchEuroAutoFormat = function(){

        // 개발자가 input 컴포넌트에 setUserNumberFormat 속성을 사용한 경우에만 적용
        $p.$(":wq(input)").wq().each(function(index, _this){

            var dataType = _this.options.dataType;
            var setUserNumberFormat = _this.options.setUserNumberFormat;

            // #,###.## 포맷
            if(gcm.NUMBER_FORMAT == 1 && setUserNumberFormat == "true"){

                if(dataType == "number"){
                    _this.setDisplayFormat("#,###");

                } else if(dataType == "float"){
                    _this.setDisplayFormat("#,###.##");
                } 
            // #.###,## 포맷    
            } else if(gcm.NUMBER_FORMAT == 2 && setUserNumberFormat == "true"){

                if(dataType == "number"){
                    // 동적으로 dataType을 euro로 변경하는 것은 웹스퀘어 스펙상 지원 안됨( _this.setDataType() 또는 _this.options.dataType)
                    // changeCurrency를 이용하면 동적 변경 됨
                    _this.changeCurrency("euro", "#.###");
                    _this.options.customModelFormatter ="scwin.inputCustomFormat";
                    _this.options.customModelUnformatter ="scwin.inputCustomUnFormat";

                } else if(dataType == "float"){
                    _this.changeCurrency("euro", "#.###,##");
                    _this.options.customModelFormatter ="scwin.inputCustomFormat";
                    _this.options.customModelUnformatter ="scwin.inputCustomUnFormat";
                }
            }

            // 개발자 정의한 displayFormat에 맞게 euroMask 변경(소수점, 콤마만 변경) 추후  반영
            //var displayFormat = _this.options.displayFormat;

            //if(com.isEmpty(displayFormat)){
            //    return false;
            //}

            //var euroMaskRest = [...displayFormat];
            //var euroMask = euroMaskRest.reduce(function(acc, cur){
            //  if(cur == ",") return acc += ".";
            //  else if(cur == ".") return acc += ",";
            //  else return acc += cur;
            //}, "");
        });
    };

    scwin.gridEuroAutoFormat = function(){

	    console.log("scwin.gridEuroAutoFormat >>>>> gcm.NUMBER_FORMAT=====", gcm.NUMBER_FORMAT);

        // 개발자가 그리드 내부 컬럼에 setUserNumberFormat 속성을 사용한 경우에만 적용
        $p.$(":wq(gridView)").wq().each(function(index, _this){

           var columnIdArr = _this.getColumnOrder(true);

           // #,###.## 포맷
           if(gcm.NUMBER_FORMAT == 1){

			   columnIdArr.forEach(function(elem){

				    var setUserNumberFormat = _this.getCellInfo(elem).options.setUserNumberFormat;
				    var dataType = _this.getDataType(elem);

				    if(setUserNumberFormat == "true"){
				        if(dataType == "number"){
				            _this.setDisplayFormat(elem, "#,###");
				        } else if(dataType == "float"){
				            _this.setDisplayFormat(elem, "#,###.##");
				        }
				    } 
				});
			/****************************************************************************
			* TO. 연구소 적원 : 아래 부분 확인해 바랍니다.
			****************************************************************************/	
            // #.###,## 포맷
            } else if(gcm.NUMBER_FORMAT == 2){

                columnIdArr.forEach(function(elem){

                    var setUserNumberFormat = _this.getCellInfo(elem).options.setUserNumberFormat;
                    var dataType = _this.getDataType(elem);

                    if(setUserNumberFormat == "true"){
                        var info = {
                            colID : elem,
                            type : "euro",
                            delimiter : ".",
                            decimalDelimiter : ",",
                            customModelFormatter : "scwin.inputCustomFormat",
                            customModelUnformatter : "scwin.inputCustomUnFormat"
                        }
                        if(elem == "type01"){
                            var info = {
                                colID : elem,
                                type : "euro",
                                format : "#.###,#"
                            }
                            //_this.changeCurrency(elem , "euro" , "#.###,#");
                            info.format = "#.###,#";
                            _this.changeCurrency(info);
                        } else if(elem == "type02"){
                            // gridView 속성에 euroMask="#.###,##"이라서 소수점 2자리까지 밖에 적용되지 않음
                            //_this.changeCurrency(elem , "euro" , "#.###,###", ".", ","); // 소수점 3자리 적용되지 않음
                            info.format = "#.###,###";
                            _this.changeCurrency(info);
                        }
                    }
                });
            }
        });
    };

    /*******************************
    * 조회조건 날짜 셋팅
    ********************************/
    scwin.setData = function() {
	    ibx_type01.setValue("12345678");       //정수
	    ibx_type02.setValue("12345678.1234");  //실수
    };

    /*******************************
    * 그리드 조회
    ********************************/
    scwin.btn_search_onclick = function() {
        dlt_sample.setJSON(scwin.jsonData1);
    };

    /*******************************
    * 엑셀 다운로드
    ********************************/
    scwin.btn_down_onclick = function(e) {
        var option = {
            type : "1",
            fileName : "data.xlsx",
            readOnlyColor : "true"
        };
        com.downloadGridExcel(grd_sample, option);
    };

    scwin.inputCustomFormat = function(realData, formattedData) {
        return realData.replace(",", ".");
    };

    scwin.inputCustomUnFormat = function(realData, formattedData) {
        return realData.replace(".", ",");
    };


    /*******************************
    * 화면 벗어날때 이벤트
    ********************************/
    scwin.onpageunload = function() {

    };

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('grd_sample_cell_0_1').innerText == '12.345.678,123';
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('grd_sample_cell_0_0').innerText == '12.345.678';
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_search').click()");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
